<style>
.router-page,.router-preview-page{--r-bg:#fff;--r-soft:#f1f5f9;--r-text:#0f172a;--r-muted:#475569;--r-line:#cbd5e1;--r-brand:#0e7490;--r-good-bg:#ecfdf5;--r-good-text:#065f46;--r-bad-bg:#fff1f2;--r-bad-text:#9f1239;--r-info-bg:#ecfeff;--r-info-text:#155e75;--r-warn-bg:#fffbeb;--r-warn-text:#92400e;color:var(--r-text)}
.dark .router-page,.dark .router-preview-page{--r-bg:#151e30;--r-soft:#202c40;--r-text:#edf2f7;--r-muted:#b8c5d6;--r-line:#41516a;--r-brand:#67e8f9;--r-good-bg:#12382c;--r-good-text:#bbf7d0;--r-bad-bg:#3d202e;--r-bad-text:#fecdd3;--r-info-bg:#123444;--r-info-text:#bae6fd;--r-warn-bg:#3c301b;--r-warn-text:#fde68a}
.router-page{max-width:1152px;margin:auto;display:grid;gap:22px}.r-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap}.r-eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.14em;font-weight:700;color:var(--r-brand)}.r-title{font-size:25px;line-height:1.3;font-weight:800;margin:5px 0 8px;color:var(--r-text)}.r-muted{color:var(--r-muted);font-size:13px;line-height:1.7}.r-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.r-card{background:var(--r-bg);border:1px solid var(--r-line);border-radius:18px;overflow:hidden;box-shadow:0 3px 16px #00000008}.r-card-body{padding:22px}.r-row{display:flex;align-items:center;justify-content:space-between;gap:12px}.r-name{font-size:18px;font-weight:750;overflow-wrap:anywhere;color:var(--r-text)}.r-address{font:12px ui-monospace,monospace;color:var(--r-muted);margin-top:7px;overflow-wrap:anywhere}.r-badge{display:inline-flex;align-items:center;gap:7px;padding:6px 10px;border-radius:30px;font-size:11px;font-weight:700;line-height:1.4;border:1px solid var(--r-line);background:var(--r-soft);color:var(--r-muted)}.r-badge[data-state=success]{background:var(--r-good-bg);color:var(--r-good-text);border-color:var(--r-good-text)}.r-badge[data-state=failed]{background:var(--r-bad-bg);color:var(--r-bad-text);border-color:var(--r-bad-text)}.r-badge[data-state=stale]{background:var(--r-warn-bg);color:var(--r-warn-text);border-color:var(--r-warn-text)}.r-badge i{width:7px;height:7px;border-radius:50%;background:currentColor;display:inline-block;flex-shrink:0}.r-operation{margin-top:12px;font-size:11px;color:var(--r-muted)}.r-resource{margin:18px 0;padding:16px;background:var(--r-soft);border:1px solid var(--r-line);border-radius:13px}.r-metrics{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.r-metric-label{display:flex;align-items:center;gap:6px;font-size:11px;color:var(--r-muted)}.r-value{font-size:19px;font-weight:750;color:var(--r-text);margin-top:7px;overflow-wrap:anywhere}.r-bar{height:6px;border-radius:6px;background:var(--r-line);overflow:hidden;margin-top:9px}.r-bar span{height:100%;display:block;background:#0891b2}.r-bar span[data-level=medium]{background:#d97706}.r-bar span[data-level=high]{background:#e11d48}.r-last{font-size:11px;color:var(--r-muted);line-height:1.7;margin-top:12px}.r-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.r-actions form{margin:0}.r-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:10px 14px;border-radius:10px;border:1px solid var(--r-line);font-size:13px;font-weight:650;color:var(--r-text);background:var(--r-bg);cursor:pointer;text-decoration:none;line-height:1.5}.r-btn:hover{background:var(--r-soft)}.r-btn:focus-visible{outline:3px solid #22d3ee;outline-offset:3px}.r-btn-primary{background:#0e7490!important;border-color:#0e7490!important;color:#fff!important}.r-btn-primary:hover{background:#155e75!important}.r-btn:disabled{opacity:.55;cursor:wait}.r-danger{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 22px;border-top:1px solid var(--r-line);background:var(--r-soft)}.r-danger a{display:inline-flex;align-items:center;gap:7px;color:var(--r-bad-text);font-size:12px;font-weight:700;text-decoration:none}.r-danger a:hover{text-decoration:underline}.r-counter{display:flex;gap:8px;flex-wrap:wrap}.r-icon{width:18px;height:18px;flex-shrink:0}.r-empty{grid-column:1/-1;border:1px dashed var(--r-line);border-radius:16px;padding:28px;text-align:center;background:var(--r-bg)}
@media(max-width:700px){.r-grid{grid-template-columns:1fr}.r-card-body{padding:18px}.r-title{font-size:22px}.r-value{font-size:17px}}
.router-preview-page [class~="bg-white"]{background-color:var(--r-bg)!important}.router-preview-page [class~="bg-slate-100"],.router-preview-page [class~="bg-slate-50"]{background-color:var(--r-soft)!important}.router-preview-page [class~="bg-cyan-50"]{background-color:var(--r-info-bg)!important;color:var(--r-info-text)!important}.router-preview-page [class~="bg-rose-50"]{background-color:var(--r-bad-bg)!important;color:var(--r-bad-text)!important}.router-preview-page [class~="text-slate-900"],.router-preview-page [class~="text-slate-700"]{color:var(--r-text)!important}.router-preview-page [class~="text-slate-600"],.router-preview-page [class~="text-slate-500"],.router-preview-page [class~="text-slate-400"]{color:var(--r-muted)!important}.router-preview-page [class~="text-rose-900"],.router-preview-page [class~="text-rose-700"]{color:var(--r-bad-text)!important}.router-preview-page [class~="text-cyan-900"]{color:var(--r-info-text)!important}.router-preview-page [class~="border-slate-200"],.router-preview-page [class~="border-slate-300"],.router-preview-page [class~="border-slate-100"]{border-color:var(--r-line)!important}.router-preview-page input[type=text]{background:var(--r-bg)!important;color:var(--r-text)!important;border-color:var(--r-line)!important}.router-preview-page input::placeholder{color:var(--r-muted)!important;opacity:.85}.router-preview-page input[type=checkbox]{accent-color:#be123c}.router-preview-page a,.router-preview-page button{transition:background-color .15s}.router-preview-page button[type=submit]{background:#be123c!important;color:#fff!important;border-color:#be123c!important}.router-preview-page button[type=submit]:hover{background:#9f1239!important}.router-flash-success{background:#ecfdf5!important;color:#065f46!important;border-color:#6ee7b7!important}.router-flash-error{background:#fff1f2!important;color:#9f1239!important;border-color:#fda4af!important}.dark .router-flash-success{background:#12382c!important;color:#bbf7d0!important;border-color:#438b68!important}.dark .router-flash-error{background:#3d202e!important;color:#fecdd3!important;border-color:#9b5064!important}
</style>
